Return the output dict as a json inside a json with the key 'code_output'. Here is the code:

```rust

    use serde_json::{Value, from_str, to_string, Map, json};
    use std::io::{self, Read};

    fn document_matrix_cipher(input: serde_json::Value) -> serde_json::Value {
    let text = input["text"].as_str().unwrap_or("");
    let key = input["key"].as_array().unwrap_or(&Vec::new())
        .iter()
        .filter_map(|v| v.as_i64())
        .map(|v| v as i32)
        .collect::<Vec<i32>>();

    if key.is_empty() || text.is_empty() {
        return serde_json::json!({"error": "Invalid input"});
    }

    // Create matrix from text - calculate size without floats
    let len = text.len();
    let mut size = 0;
    while size * size < len {
        size += 1;
    }

    let mut matrix = vec![vec![0u8; size]; size];

    for (i, c) in text.bytes().enumerate() {
        if i >= size * size { break; }
        matrix[i / size][i % size] = c;
    }

    // Apply transformations based on key
    for &k in &key {
        match k.abs() % 4 {
            0 => { // Rotate rows
                let shift = k.abs() as usize % size;
                let direction = k.signum();
                for row in &mut matrix {
                    let orig = row.clone();
                    for i in 0..size {
                        let new_pos = if direction > 0 {
                            (i + shift) % size
                        } else {
                            (i + size - shift) % size
                        };
                        row[new_pos] = orig[i];
                    }
                }
            },
            1 => { // Rotate columns
                let shift = k.abs() as usize % size;
                let direction = k.signum();
                let orig = matrix.clone();
                for col in 0..size {
                    for row in 0..size {
                        let new_row = if direction > 0 {
                            (row + shift) % size
                        } else {
                            (row + size - shift) % size
                        };
                        matrix[new_row][col] = orig[row][col];
                    }
                }
            },
            2 => { // Transpose matrix
                let orig = matrix.clone();
                for row in 0..size {
                    for col in 0..size {
                        matrix[col][row] = orig[row][col];
                    }
                }
            },
            3 => { // XOR with key value
                let xor_val = k.abs() as u8;
                for row in 0..size {
                    for col in 0..size {
                        if matrix[row][col] != 0 {
                            matrix[row][col] ^= xor_val;
                        }
                    }
                }
            },
            _ => {}
        }
    }

    // Extract results
    let mut rowwise = String::new();
    let mut colwise = String::new();

    for row in 0..size {
        for col in 0..size {
            if matrix[row][col] != 0 {
                rowwise.push(matrix[row][col] as char);
            }
        }
    }

    for col in 0..size {
        for row in 0..size {
            if matrix[row][col] != 0 {
                colwise.push(matrix[row][col] as char);
            }
        }
    }

    serde_json::json!({
        "rowwise": rowwise,
        "columnwise": colwise,
        "dimensions": size,
        "operations": key.len()
    })
}

    fn main() {
        let mut buf = String::new();
        io::stdin().read_to_string(&mut buf).unwrap();
        let inp: Value = from_str(&buf).unwrap();
        let out = document_matrix_cipher(inp);
        println!("{}", to_string(&out).unwrap());
    }

