```python
def document_transformer(data):
    result = {"transformed": {}, "metrics": {}}

    def process_text(text):
        if not isinstance(text, str):
            return text

        # Position-based character transformation
        chars = []
        for i, c in enumerate(text):
            if c.isalpha():
                base = ord('A') if c.isupper() else ord('a')
                # Shift based on position and character value
                shift = (i % 8) + (ord(c.lower()) - ord('a')) % 4 + 1
                new_char = chr((ord(c) - base + shift) % 26 + base)
                chars.append(new_char)
            else:
                chars.append(c)

        # Word-level transformations
        words = ''.join(chars).split()
        for i in range(len(words)):
            if i % 2 == 1 and len(words[i]) > 1:  # Every odd-indexed word
                words[i] = words[i][::-1]  # Reverse
            elif i % 3 == 0 and len(words[i]) > 0:  # Every third word
                words[i] = words[i][0].upper() + words[i][1:] if len(words[i]) > 1 else words[i].upper()

        return ' '.join(words)

    def process_value(item, depth=0):
        if depth > 3:  # Limit recursion depth
            return str(item)

        if isinstance(item, str):
            return process_text(item)
        elif isinstance(item, int):
            # Transform integers using digit operations
            digits = [int(d) for d in str(abs(item))]
            digit_sum = sum(digits)
            digit_product = 1
            for d in digits:
                digit_product *= max(1, d)  # Avoid multiplying by zero

            # Combine operations deterministically
            return item + digit_sum + (digit_product % 100)
        elif isinstance(item, list) and len(item) <= 8:
            return [process_value(x, depth+1) for x in item]
        elif isinstance(item, dict) and len(item) <= 5:
            return {k: process_value(v, depth+1) for k, v in item.items()}
        else:
            return str(item)

    # Process based on input type
    if isinstance(data, dict):
        for key, value in data.items():
            result["transformed"][key] = process_value(value)

        # Calculate metrics
        string_keys = sum(1 for v in data.values() if isinstance(v, str))
        int_keys = sum(1 for v in data.values() if isinstance(v, int))
        complex_keys = sum(1 for v in data.values() if isinstance(v, (dict, list)))

        result["metrics"] = {
            "key_count": len(data),
            "string_values": string_keys,
            "int_values": int_keys,
            "complex_values": complex_keys
        }

    elif isinstance(data, list):
        processed = [process_value(item) for item in data[:10]]  # Limit to first 10 items
        result["transformed"]["items"] = processed

        # Calculate metrics
        string_items = sum(1 for item in data if isinstance(item, str))
        int_items = sum(1 for item in data if isinstance(item, int))

        result["metrics"] = {
            "item_count": len(data),
            "string_items": string_items,
            "int_items": int_items,
            "processed_count": len(processed)
        }

    else:
        # Process single value
        result["transformed"]["value"] = process_value(data)
        result["metrics"]["type"] = type(data).__name__

    # Calculate complexity score
    complexity = 0
    for value in result["transformed"].values():
        complexity += len(str(value)) * 2

    result["metrics"]["complexity"] = complexity

    return result
