def document_analyzer(input_data):
    result = {"elements": [], "analytics": {}, "metadata": {}}

    # Normalize input to handle various formats
    if isinstance(input_data, (int, str, bool)) or input_data is None:
        data = {"content": input_data}
    else:
        data = input_data

    # Extract the main content from various possible structures
    content = None
    for key in ["data", "content", "value", "items"]:
        if key in data:
            content = data[key]
            break
    if content is None:
        content = data

    # Process based on content type
    if isinstance(content, list):
        # Flatten one level if nested lists exist
        flattened = []
        for item in content:
            if isinstance(item, list):
                flattened.extend(item[:5])  # Limit nested items
            else:
                flattened.append(item)

        # Transform each item based on type and position
        transformed = []
        for i, item in enumerate(flattened[:16]):
            if isinstance(item, int):
                if i % 3 == 0:  # Position 0, 3, 6...
                    transformed.append(item * 2 - 1)
                elif i % 3 == 1:  # Position 1, 4, 7...
                    transformed.append((item ** 2) % 100)
                else:  # Position 2, 5, 8...
                    transformed.append(sum(int(d) for d in str(abs(item))))
            elif isinstance(item, str):
                if item and item[0].isalpha():
                    # Sum of letter positions (a=1, b=2, etc.)
                    transformed.append(sum((ord(c.lower()) - 96) for c in item if c.isalpha()) % 100)
                else:
                    # Count character types
                    digits = sum(1 for c in item if c.isdigit())
                    letters = sum(1 for c in item if c.isalpha())
                    transformed.append(digits * 10 + letters)
            else:
                transformed.append(0)

        result["elements"] = transformed[:10]

        # Calculate analytics
        if transformed:
            result["analytics"]["sum"] = sum(transformed)
            result["analytics"]["count"] = len(transformed)

            # Find most frequent value
            frequency = {}
            for val in transformed:
                frequency[val] = frequency.get(val, 0) + 1
            if frequency:
                most_common = max(frequency.items(), key=lambda x: x[1])
                result["analytics"]["mode"] = most_common[0]
                result["analytics"]["frequency"] = most_common[1]

    elif isinstance(content, dict):
        # Process dictionary structure
        keys = list(content.keys())
        values = list(content.values())

        # Transform values
        processed = []
        for i, val in enumerate(values[:10]):
            if isinstance(val, int):
                processed.append((val * (i + 1)) % 100)
            elif isinstance(val, str):
                processed.append(len(val))
            elif isinstance(val, list):
                processed.append(len(val))
            else:
                processed.append(0)

        result["elements"] = processed
        result["metadata"]["keys"] = keys[:5]

        # Calculate analytics
        if processed:
            result["analytics"]["sum"] = sum(processed)
            result["analytics"]["count"] = len(processed)

    elif isinstance(content, int):
        # Generate sequence using Collatz conjecture
        sequence = []
        current = content
        for _ in range(min(8, abs(content) + 1)):
            sequence.append(current)
            if current % 2 == 0:  # Even number
                current = current // 2
            else:  # Odd number
                current = 3 * current + 1

        result["elements"] = sequence
        result["analytics"]["steps"] = len(sequence)

        # Digit analysis
        digits = [int(d) for d in str(abs(content))]
        result["metadata"]["digits"] = digits
        result["analytics"]["digit_sum"] = sum(digits)

    elif isinstance(content, str):
        # Character analysis
        result["metadata"]["length"] = len(content)
        result["metadata"]["letters"] = sum(1 for c in content if c.isalpha())
        result["metadata"]["digits"] = sum(1 for c in content if c.isdigit())

        # Either word analysis or character position analysis
        if " " in content:
            words = content.split()
            result["elements"] = [len(w) for w in words[:10]]
            result["analytics"]["word_count"] = len(words)
        else:
            char_values = []
            for i, char in enumerate(content[:10]):
                if char.isalpha():
                    # Position in alphabet * position in string
                    val = (ord(char.lower()) - 96) * (i + 1) % 100
                    char_values.append(val)
                elif char.isdigit():
                    char_values.append(int(char) * (i + 1))
                else:
                    char_values.append(i + 1)
            result["elements"] = char_values

    # Process additional metadata if present
    if "metadata" in data and isinstance(data["metadata"], dict):
        meta = data["metadata"]
        result["metadata"]["meta_count"] = len(meta)

        # Extract specific metadata fields
        for key in ["priority", "source", "version"]:
            if key in meta:
                result["metadata"][key] = meta[key]

        # Process tags if present
        if "tags" in meta and isinstance(meta["tags"], list):
            result["metadata"]["tags"] = meta["tags"][:3]  # Limit to 3 tags

    return result
